void fn0() {





  final n = 4;
  final m = 3;
  final b = 1;
  final t = 2;

  final dp = List.filled(n + 1, 0);
  final x = List.filled(n + 1, 0);
  final y = List.filled(n + 1, 0);

  for (var i = 1; i <= n; i++) {
    final tX = ((i - 1) % t + t) % t;
    final tY = ((i - 1) % t + t) % t;
    x[i] = tX;
    y[i] = tY;
  }

  for (var i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + b + x[i] * y[i];
  }

  final minDist = List.filled(n + 1, 0);
  final minDistIdx = List.filled(n + 1, 0);

  for (var i = 1; i <= n; i++) {
    for (var j = 0; j < i; j++) {
      final d = dp[i] - dp[j] - (x[i] - x[j]).abs() - (y[i] - y[j]).abs();
      if (d < minDist[i]) {
        minDist[i] = d;
        minDistIdx[i] = j;
      } else if (d == minDist[i] && d > 0) {
        if (x[i] < x[j]) {
          minDistIdx[i] = j;
        } else if (x[i] == x[j] && y[i] < y[j]) {
          minDistIdx[i] = j;
        }
      }
    }
  }

  final uniqueDistances = minDist.toSet();

  print('x | y | d | idx');
  for (final d in uniqueDistances) {
    final uniqueIdx = minDist.indexOf(d);
    final idx = minDistIdx[uniqueIdx];
    print('  ${x[idx]} | ${y[idx]} | $d | $uniqueIdx');
  }

  final minDistMap = <int, List<int>>{};
  for (var i = 1; i <= n; i++) {
    final d = minDist[i];
    final idx = minDistIdx[i];
    if (!minDistMap.containsKey(d)) {
      minDistMap[d] = [];
    }
    minDistMap[d]!.add(idx);
  }

  print('');
  print('d | idxs');
  for (final d in uniqueDistances) {
    print('$d | ${minDistMap[d]}');
  }
}

