void fn0() {

  int n = 4;

  void generateSubsets(List<int> arr, int start, List<int> curr, Set<List<int>> result) {
    if (start == arr.length) {
      result.add(curr.toSet());
      return;
    }
    generateSubsets(arr, start + 1, curr, result);
    curr.add(arr[start]);
    generateSubsets(arr, start + 1, curr, result);
    curr.removeLast();
  }

  List<int> arr = List.generate(n, (i) => i + 1);
  Set<List<int>> subsets = {};
  generateSubsets(arr, 0, [], subsets);

  Map<List<int>, int> binarySubsets(List<int> arr, int start) {
    if (start == arr.length) {
      return <int, int>{};
    }
    Map<List<int>, int> left = {};
    for (int i = 0; i <= start; i++) {
      List<int> curr = List.generate(i + 1, (j) => arr[j]);
      left[curr] = binarySubsets(arr, i + 1)[curr] ?? 0;
    }
    left[arr] = 1;
    Map<List<int>, int> right = {};
    for (int i = start + 1; i < arr.length; i++) {
      right[arr.sublist(start + 1, i + 1)] = 1;
    }
    Map<List<int>, int> result = {};
    for (var key in left.keys) {
      int b = key[0];
      for (var k in right.keys) {
        int a = k[0];
        if (b <= a) continue;
        List<int> curr = List.generate(key.length + k.length, (j) => key[j] > k[j] ? key[j] : k[j]);
        result[curr] = (result[curr] ?? 0) + left[key]! * right[k]!;
      }
    }
    return result;
  }

  Map<List<int>, int> binary = binarySubsets(arr, 0);
  List<List<int>> listSubsets = binary.keys.toList();
  listSubsets.sort((a, b) {
    int bySize = a.length.compareTo(b.length);
    if (bySize != 0) return bySize;
    return a[0].compareTo(b[0]);
  });

  print(listSubsets);
}

