@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart fn0.dart [phrase]');
    print('  where [phrase] is the word or phrase to be searched.');
    print('  The search will be case-insensitive and limited to the first 1000 characters of the word or phrase.');
    print('  The results will be printed to the console.');
    return;
  }

  List<String> argsList = args.toList();

  String word = argsList[0];
  int maxLen = argsList.length;

  if (word.length > 1000) {
    word = word.substring(0, 1000);
  }

  int maxLenT = word.length;
  int totalSubsets = 1 << maxLenT;

  List<bool> dp = List.filled(totalSubsets, false);
  dp[0] = true;

  for (int len = 1; len <= maxLen; len++) {
    List<bool> nextDp = List.filled(totalSubsets, false);
    for (int prevMask = 0; prevMask < totalSubsets; prevMask++) {
      if (dp[prevMask] == false) continue;
      bool includeLetter = (prevMask >> len) & 1 == 1;
      for (int newMask = 0; newMask < totalSubsets; newMask++) {
        if (includeLetter && (newMask & (1 << len)) == 0) {
          nextDp[newMask] = true;
        }
        if (!includeLetter && (newMask & (1 << len)) == 0) {
          nextDp[newMask] = true;
        }
      }
    }
    dp = nextDp;
  }

  Set<String> allSubsets = {};

  for (int mask = 0; mask < totalSubsets; mask++) {
    if (dp[mask]) {
      allSubsets.add(word.substring(0, maxLenT - mask));
    }
  }

  Map<String, int> counts = {};
  for (String s in allSubsets) {
    counts[s] = (counts[s] ?? 0) + 1;
  }

  List<String> sorted = counts.keys.toList();
  sorted.sort();

  print('Word: "$word"');
  print('Subsets: ${allSubsets.toSet().length}');
  print('Counts: $counts');
}

