void fn0() {

  List<String> rows = ['a', 'b', 'c'];
  int cols = rows.length;

  void printBoard(List<List<int>> board) {
    for (var row in board) {
      print(row.join(' '));
    }
    print('');
  }

  void place(int col, int row) {

    if (board[row][col] != 0) return;
    board[row][col] = row;

    if (row - col == 0) {

      List<int> sol = [];
      for (int r = 0; r < rows.length; r++) {
        for (int c = 0; c < cols; c++) {
          if (board[r][c] == row) sol.add(c);
        }
      }
      print('Solution: ${sol.toSet()}');
      return;
    }

    for (int nextCol = 1; nextCol <= cols; nextCol++) {
      if (nextCol - col == row - 1) {

        int nextRow = (row + nextCol) % rows.length;
        place(nextCol, nextRow);
      }
    }
  }

  List<List<int>> board = List.generate(rows.length, (_) => List.filled(cols, 0));

  for (int col = 0; col < cols; col++) {
    for (int row = 0; row < rows.length; row++) {
      place(col, row);
    }
  }

  printBoard(board);
}

