Map<String, int> fn0(List<String> events) {
  List<int> stack = [0];
  List<String> log = [];
  Map<String, int> totals = {};

  List<int> parse(String token) {
    if (token.isEmpty) return [0, 0];
    List<String> parts = token.split(',');
    int x = int.parse(parts[0]);
    int y = int.parse(parts[1]);
    int size = int.parse(parts[2]);
    return [x, y, size];
  }

  void process(List<int> p) {
    int x = p[0];
    int y = p[1];
    int size = p[2];
    for (int i = 0; i < stack.length; i++) {
      int total = stack[i];
      int code = x + y + size * 1000;
      if (total == code) {
        log.add('$i:$total');
        stack.removeLast();
      } else {
        stack.add(total);
      }
    }
  }

  for (String event in events) {
    if (event == '(') {
      stack.add(0);
    } else if (event == ')') {
      while (stack.isNotEmpty) {
        int total = stack.removeLast();
        if (total > 0) log.add('$total');
      }
    } else if (event == '[') {
      log.add('[$total]');
    } else if (event == '|') {
      if (log.isNotEmpty) {
        totals[log.last] = (totals[log.last] ?? 0) + stack.removeLast();
      }
    } else {
      List<int> p = parse(event);
      process(p);
    }
  }

  Map<String, int> finalTotals = {};
  for (var entry in log) {
    List<String> parts = entry.split(':');
    finalTotals[parts[0]] = (finalTotals[parts[0]] ?? 0) + int.parse(parts[1]);
  }
