List<String> fn0(List<String> commands, int startDay, int endDay) {
  if (commands.isEmpty || startDay > endDay) return [];

  final Map<String, List<int>> dayTotals = {
    'Monday': [0, 0],
    'Tuesday': [0, 0],
    'Wednesday': [0, 0],
    'Thursday': [0, 0],
    'Friday': [0, 0],
    'Saturday': [0, 0],
    'Sunday': [0, 0],
  };

  final List<String> events = [];

  void processCommand(String cmd) {
    if (cmd == '!') {
      events.add('$startDay..${endDay - 1}: ${dayTotals["Sunday"][0]}');
    } else {
      final parts = cmd.split(' ');
      final dayName = parts[0];
      final total = int.parse(parts[1]);

      dayTotals[dayName]![0] += total;
      dayTotals[dayName]![1] += 1;

      events.add('$startDay..${endDay - 1}: ${dayTotals[dayName][0]}');
    }
  }

  void execute(String cmd) {
    if (cmd == '!') {
      if (events.isNotEmpty) events.removeLast();
    } else {
      processCommand(cmd);
    }
  }

  final List<String> commandsSorted = [...commands];
  commandsSorted.sort();

  for (final cmd in commandsSorted) {
    execute(cmd);
  }

  final List<String> result = [];
  for (final day in startDay..to..endDay) {
    final dayStr = day.toString().padLeft(3, '0');
    final total = dayTotals['$dayStr'][0];
    final count = dayTotals['$dayStr'][1];
    if (total != 0 && count > 1) result.add('$dayStr: $total / $count');
  }

  return result;
}

