  void mergeSort(List<int> arr, int low, int high) {
    if (low < high) {
      int mid = low + (high - low) ~/ 2;
      mergeSort(arr, low, mid);
      mergeSort(arr, mid, high);

      int i = low;
      int j = mid;
      List<int> temp = [];

      while (i < mid && j < high) {
        if (arr[i] <= arr[j]) {
          temp.add(arr[i]);
          i++;
        } else {
          temp.add(arr[j]);
          j++;
        }
      }

      while (i < mid) temp.add(arr[i++]);
      while (j < high) temp.add(arr[j++]);

      for (int k = low; k < high; k++) arr[k] = temp[k];
    }
  }

  mergeSort(sortedList, 0, sortedList.length);

  print('Merge-Sorted List: $sortedList');

  List<int> rotatedList = List<int>.from(sortedList);
  rotateList(rotatedList);

  print('Rotated List: $rotatedList');
}

void rotateList(List<int> arr) {
  int n = arr.length;
  if (n == 0 || n % 2 == 0) return;

  List<int> temp = List<int>.from(arr);
  int k = n ~/ 2;

  for (int i = 0; i < n; i++) {
    if (i < k) {
      temp[(i + k) % n] = arr[i];
    } else {
      temp[(i - k) % n] = arr[i];
    }
  }

  for (int i = 0; i < n; i++) arr[i] = temp[i];
}

