  for (int j = 1; j < columns; j++) {
    for (int i = 0; i < rows.length; i++) {
      int best = dp[i][j - 1];
      if (i > 0) {
        int prev = dp[i - 1][j - 1];
        if (prev < best) {
          best = prev;
        }
      }
      dp[i][j] = best + rows[i].length - j;
    }
  }

  int ans = dp[0][columns - 1];
  for (int i = 1; i < rows.length; i++) {
    if (dp[i][columns - 1] < ans) {
      ans = dp[i][columns - 1];
    }
  }

  print(ans);
