  Map<int, int> stockUnits = {};
  for (int i = 0; i < itemCount.length; i++) {
    stockUnits[itemCount[i]] = (stockUnits[itemCount[i]] ?? 0) + 1;
  }

  List<int> multipliers = [2, 3, 5, 7];

  Map<int, List<int>> itemsWithMultipliers = {};
  for (int multiplier in multipliers) {
    itemsWithMultipliers[multiplier] = [];
  }

  void recurse(int index, List<int> path) {
    if (index == itemCount.length) {
      for (int m in multipliers) {
        List<int> sub = [...path, m];
        itemsWithMultipliers[m]!.add(sub);
      }
      return;
    }

    for (int i = index; i < itemCount.length; i++) {
      int current = itemCount[i];
      if (stockUnits.containsKey(current)) {
