        if (count > 0) {
          path.add(current);
          stockUnits[current] = count - 1;
          recurse(i + 1, path);
          path.removeLast();
          stockUnits[current] = count;
        }
      }
    }
  }

  recurse(0, []);

  for (int m in multipliers) {
    List<int> sub = [...path, m];
    itemsWithMultipliers[m]!.add(sub);
  }

