void fn0() {

  List<String> args = [];
  String target = '';
  int targetCode = 0;
  bool hasTarget = false;

  for (int i = 0; i < args.length; i++) {
    String arg = args[i];
    if (arg == '--target') {
      hasTarget = true;
    } else if (hasTarget) {
      target = arg;
      targetCode = arg.codeUnitAt(0);
    }
  }

  if (!hasTarget) {
    print('Usage: --target <char>');
    return;
  }

  List<String> lines = [];
  String current = '';
  bool insideComment = false;
  int currentLine = 0;

  List<List<int>> history = [];

  List<List<String>> tokens = [];

  void processLine(String line) {
    String trimmed = line.trim();
    if (trimmed.isEmpty) return;

    if (trimmed.startsWith('#')) {
      insideComment = true;
      return;
    }

    if (insideComment) {
      return; 
    }

    if (trimmed.startsWith('"')) {
      current = trimmed;
      return;
    }

    List<String> parts = trimmed.split('|');
    if (parts.length != 2) return;

    String token = parts[0].trim();
    if (token.isEmpty) return;

    List<String> words = token.split(' ');
    if (words.length != 2) return;

    String word = words[0];
    int lineNum = int.tryParse(words[1]);
    if (lineNum == null || lineNum < 0) return;

    tokens.add([word, lineNum]);
    history.add([word, lineNum]);

    if (word == target) {
      currentLine = lineNum;
      return;
    }

    for (var token in words) {
      if (token == target) {
        currentLine = lineNum;
        return;
      }
    }
  }

  for (int line = 0; line < 100; line++) {
    String lineChar = String.fromCharCode(line + 48);
    print(lineChar);

    String lineStr = '';
    for (int i = 0; i < lineChar.length; i++) {
      lineStr += lineChar;
      if (lineStr.isEmpty) continue;

      processLine(lineStr);

      if (current.isNotEmpty) {
        print('  | ${currentLine + 1}: ${current}');
      }

      lineStr = '';
    }
  }

  print('');
  print('Tokens: ${tokens.toString()}');
  print('History: ${history.toString()}');
}

