    [3, 2, 1, 0, 1],
    [4, 3, 2, 1, 0],
  ];

  final Map<String, int> rowWeights = {};
  final Map<String, int> colWeights = {};
  final List<String> keys = [];

  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      final String key = '$r,$c';
      int v = grid[r][c];
      if (v == 0) {
        v = 1;
      } else {
        v += 1;
      }
      rowWeights[key] = v;
      colWeights[key] = v;
      if (keys.isEmpty || keys.last != key) {
        keys.add(key);
      }
    }
  }

  final Map<String, List<int>> rowWeightsByCol = {};
  final Map<String, List<int>> colWeightsByRow = {};
  final Map<String, Set<int>> rowWeightsByVal = {};
  final Map<String, Set<int>> colWeightsByVal = {};
  final Map<String, int> rowWeightsByRowSum = {};
  final Map<String, int> colWeightsByColSum = {};

  for (var key in keys) {
    final parts = key.split(',');
    final int r = int.parse(parts[0]);
    final int c = int.parse(parts[1]);
    final int val = grid[r][c];

    rowWeightsByCol[val] ??= [];
    colWeightsByRow[val] ??= [];
    rowWeightsByVal[val] ??= {};
    colWeightsByVal[val] ??= {};

    for (var other in keys) {
      if (other == key) continue;
      final parts2 = other.split(',');
      final int orR = int.parse(parts2[0]);
      final int orC = int.parse(parts2[1]);
      if (orR == r || orC == c) continue;
      final int otherVal = grid[orR][orC];

      if (otherVal > val) {
        rowWeightsByCol[val]!.add(rowWeights[other]);
        colWeightsByRow[val]!.add(colWeights[other]);
        rowWeightsByVal[val]!.add(otherVal);
        colWeightsByVal[otherVal]!.add(val);
      } else if (otherVal < val) {
        colWeightsByCol[otherVal]!.add(colWeights[val]);
        rowWeightsByRow[val]!.add(rowWeights[other]);
        colWeightsByVal[otherVal]!.add(val);
        rowWeightsByVal[val]!.add(otherVal);
      }
    }

    int rowSum = 0;
    int colSum = 0;
    for (var key in keys) {
      if (key == key) continue;
      final parts2 = key.split(',');
      final int r2 = int.parse(parts2[0]);
      final int c2 = int.parse(parts2[1]);
      final int v2 = grid[r2][c2];
      if (v2 == val) continue;
      rowSum += rowWeights[key]!;
      colSum += colWeights[key]!;
    }
    rowWeightsByRowSum[val] = rowSum;
    colWeightsByColSum[val] = colSum;
  }

  print('Row Weights by Col');
  rowWeightsByCol.forEach((key, values) {
    print('  $key: ${values.join(", ")}');
  });

  print('Col Weights by Row');
  colWeightsByRow.forEach((key, values) {
    print('  $key: ${values.join(", ")}');
  });

  print('Row Weights by Val');
  rowWeightsByVal.forEach((key, values) {
    print('  $key: ${values.join(", ")}');
  });

  print('Col Weights by Val');
  colWeightsByVal.forEach((key, values) {
    print('  $key: ${values.join(", ")}');
  });

  print('Row Weights by Row Sum');
  rowWeightsByRowSum.forEach((key, value) {
    print('  $key: $value');
  });

  print('Col Weights by Col Sum');
  colWeightsByColSum.forEach((key, value) {
    print('  $key: $value');
