List<int> fn0(List<String> phases, String start, int limit) {
  List<int> result = [];
  if (phases.isEmpty || limit <= 0) return result;
  Set<String> validStarts = {};
  for (String p in phases) {
    if (p.isNotEmpty) {
      validStarts.add('${p[0]}-${p[p.length - 1]}');
    }
  }
  if (validStarts.isEmpty) return result;
  List<List<int>> runs = [];
  List<List<int>> openRuns = [];
  List<int> pending = [];
  for (String s in validStarts) {
    List<int> p = s.split('-');
    if (p.length != 2) continue;
    int start = int.parse(p[0]);
    int end = int.parse(p[1]);
    if (start >= end) continue;
    if (pending.isNotEmpty && pending.last == start) {
      pending.removeLast();
      runs.add([start, end]);
    } else {
      pending.add(start);
      openRuns.add([start, end]);
    }
  }
  while (pending.isNotEmpty) {
    int s = pending.removeAt(0);
    for (List<int> op in openRuns) {
      int e = op[1];
      if (s >= e) continue;
      if (s + limit > e) {
        runs.add([s, limit > e ? e : limit]);
      } else {
        runs.add([s, e]);
      }
    }
  }
  runs.sort((a, b) => a[0].compareTo(b[0]));
  for (List<int> run in runs) {
    if (run[1] <= limit) {
      result.add(run[1]);
    }
  }
  return result;
}

