    return result;
  }
  Set<String> used = {};
  for (String row in rows) {
    for (int j = 0; j < row.length; j++) {
      String cell = '${row[j]}:$j';
      if (!used.contains(cell)) {
        used.add(cell);
      }
    }
  }
