  }
  List<String> keys = used.toList();
  keys.sort((a, b) {
    String pa = a[0], pb = b[0];
    int da = int.parse(a[1]), db = int.parse(b[1]);
    return (pa != pb) ? pa.compareTo(pb) : da - db;
  });
  List<String> counts = List.filled(keys.length, 0);
  int rowCount = 0, colCount = 0;
  for (String key in keys) {
    String cell = key[0];
    int row = int.parse(key[1]), col = int.parse(key[2]);
    if (cell != '.' && cell != '#') {
      continue;
    }
    String neighbor = '${cell}';
    if (row > 0) neighbor = '$neighbor:${row - 1}';
    if (col > 0) neighbor = '$neighbor:$col - 1';
    if (row < rows.length - 1) neighbor = '$neighbor:${row + 1}';
    if (col < rows[row].length - 1) neighbor = '$neighbor:$col + 1';
