    }
    counts[rowCount] += cell == '.' ? 1 : 2;
    colCount++;
  }
  for (int c = 0; c < counts.length; c++) {
    if (counts[c] >= minGap && colCount > 0) {
      result.add('$c:$colCount');
    }
  }
  return result;
}

