  const Point.leftTop() : this(0, 0);

  const Point.infinity() : this(0, 0);

  @override
  String toString() => '($x, $y)';

  const Point operator +(const Point other) => Point(x + other.x, y + other.y);

  const Point operator -(const Point other) => Point(x - other.x, y - other.y);

  const Point operator *(double scale) => Point(x * scale, y * scale);

  const Point operator /(double scale) => Point(x / scale, y / scale);

  const Point operator ^(const Point other) {
    final dx = x - other.x;
    final dy = y - other.y;
    return Point(dx * dx + dy * dy, dx * dy);
  }

  const Point operator ==(const Point other) => x == other.x && y == other.y;

  const Point operator !=(const Point other) => x != other.x || y != other.y;
}

class Vector extends Point {
