  const Vector operator *(double scale) => Vector(dx * scale, dy * scale);

  const Vector operator /(double scale) => Vector(dx / scale, dy / scale);

  const Vector operator ^(const Point other) => Point(dx * other.x, dy * other.y);

  const Vector operator ==(const Vector other) => dx == other.dx && dy == other.dy;

  const Vector operator !=(const Vector other) => dx != other.dx || dy != other.dy;
}

class Segment extends Point {
  final Point start;
  final Point end;

  const Segment(this.start, this.end);

  @override
  String toString() => '${start} - $end';

  const Vector direction() => (end - start);

  const Vector unitDirection() => direction() / direction().magnitude;

  const double length() => start.distanceTo(end);

  const Point project(const Vector vector) => start + vector * (vector ^ start);

  const Point nearestPoint(const Vector vector) {
    final projection = project(vector);
    final distance = (projection - start).magnitude;
    final unit = unitDirection();
    return projection + unit * distance;
  }

  const Point farthestPoint(const Vector vector) {
    final projection = project(vector);
    final distance = (projection - start).magnitude;
    final unit = unitDirection();
    return projection + unit * (distance * 2);
  }
}

