  const Distance.unitOrigin() : this(0.0, 0.0);

  const Distance.unitOriginOrigin() : this(0.0, 0.0);

  const Distance.origin(double y) : this(0.0, y);

  const Distance.unitY(double x) : this(x, 1.0);

