  const Distance.unitX(double y) : this(1.0, y);

  const Distance.originY(double x) : this(x, 0.0);

  double get magnitude => sqrt(dx * dx + dy * dy);

  double get manhattan => dx + dy;

  double dot(Distance d) => dx * d.dx + dy * d.dy;

