void fn0(List<String> args) {

  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    int squareRoot = n.abs().sqrt();
    for (int i = 3; i * i <= squareRoot; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }

  bool isPalindrome(String s) {
    int left = 0;
    int right = s.length - 1;
    while (left < right) {
      if (s[left] != s[right]) return false;
      left++;
      right--;
    }
    return true;
  }

  bool isBalanced(String s) {
    int open = 0;
    for (int i = 0; i < s.length; i++) {
      String c = s[i];
      if (c == '[') open++;
      else if (c == ']') open--;
      else if (open != 0) return false;
    }
    return open == 0;
  }

  bool isPrimeAndPalindromeAndBalanced(String s) {
    return isPrime(s.length) &&
        isPalindrome(s) &&
        isBalanced(s);
  }

  List<String> codes = ['123456789', '123456790', '1234567890'];

  for (String code in codes) {
    String s = code.toString();
    String decoded = '';

    for (int i = 0; i < s.length; i++) {
      int digit = s.codeUnitAt(i) - 48;
      if (isPrimeAndPalindromeAndBalanced(s.substring(i))) {
        decoded += '$digit';
      }
    }

    print(s);
    print(decoded);
    print('---');
  }
}

