void fn0() {

  List<String> words = ['a', 'ab', 'abc', 'abcd', 'abcde', 'abcdef', 'abcdefg', 'abcdefgh', 'abcdefghi', 'abcdefghij'];

  int countSubstrings(String word) {
    return countSubstrings(word, 0, word.length);
  }

  int countSubstrings(String word, int start, int end) {
    if (start == end - 1) {
      return 1;
    }
    if (start > end - 1) {
      return 0;
    }

    int count = 0;
    for (int i = start; i < end - 1; i++) {
      String left = word.substring(start, i + 1);
      String right = word.substring(i + 1, end);
      if (left == right) {
        int leftCount = countSubstrings(left, start, i + 1);
        int rightCount = countSubstrings(right, i + 1, end);
        count += leftCount * rightCount;
      }
    }

    int diagonalCount = 0;
    if (word.length % 2 == 0 && start == 0 && end == word.length) {
      String diagonal = word.substring(0, word.length ~/ 2);
      diagonalCount = countSubstrings(diagonal, 0, word.length ~/ 2);
    }

    return count + diagonalCount;
  }

  print(words);
  for (String word in words) {
    print('$word -> ${countSubstrings(word)}');
  }
}

