    (i) => List.generate(
      9,
      (j) => i == 0 ? j + 1 : j == 0 ? i + 1 : i > j ? i + 1 : j + 1,
    ),
  );

  void place(int row, int col, int num) {
    if (num < 0 || num > 9) return;
    if (board[row][col] != 0) return;
    board[row][col] = num;

    bool safe = true;
    for (int r = 0; r < 9; r++) {
      for (int c = 0; c < 9; c++) {
        if (board[r][c] == num && (r == row || c == col)) {
          safe = false;
          break;
        }
      }
      if (!safe) break;
    }

    if (safe) {
      if (row == 8 && col == 8) {
        printBoard(board, '◼︎');
        return;
      }
      place(row + 1, col, num);
      place(row, col + 1, num);
    } else {
      board[row][col] = 0;
    }
  }

  for (int r = 0; r < 9; r++) {
    for (int c = 0; c < 9; c++) {
      place(r, c, board[r][c]);
    }
  }
