void fn0() {

  bool checkDigit(String barcode) {
    int sum = 0;
    for (int i = 0; i < barcode.length; i++) {
      sum += barcode.codeUnitAt(i) - 48;
    }
    return sum % 9 == barcode.codeUnitAt(barcode.length - 1) - 48;
  }

  String parse(String barcode) {
    if (barcode.isEmpty) return '';
    if (barcode.length == 1) return barcode;
    int mid = barcode.length ~/ 2;
    String left = parse(barcode.substring(0, mid));
    String right = parse(barcode.substring(mid));
    if (left.isEmpty && right.isEmpty) return '';
    if (left.length == 1 && right.length == 1) {
      return left + right;
    }
    List<String> parts = barcode.length == 3 ? ['+', '-', '?'] : ['*', '?', '?'];
    List<String> results = [];
    for (int i = 0; i < parts.length; i++) {
      String part = parts[i];
      String leftDigit = left[i];
      String rightDigit = right[i];
      results.add(leftDigit + rightDigit == part ? part : '');
    }
    if (results.isEmpty) return '';
    String best = results[0];
    int bestLen = 1;
    for (int i = 1; i < results.length; i++) {
      int len = results[i].length;
      if (len > bestLen) {
        best = results[i];
        bestLen = len;
      }
    }
    return best.isEmpty ? '' : best;
  }

  String encode(String input) {
    if (input.isEmpty) return '';
    List<int> codes = [];
    for (int i = 0; i < input.length; i++) {
      codes.add(input.codeUnitAt(i) - 48);
    }
    int first = codes[0];
    int last = codes[codes.length - 1];
    String result = first == last ? '${first * 2}' : '${first + last}';
    return result + parse(codes.sublist(1, codes.length - 1));
  }

  String testBarcodes = '123456789123456789';
  print('Barcode   |   Parsed  |   Encoded');
  print('----------|----------|----------');
  for (int i = 0; i < testBarcodes.length; i++) {
    String barcode = testBarcodes.substring(i, i + 1);
    String parsed = parse(barcode);
    if (parsed.isEmpty) {
      print('$barcode   |   ${checkDigit(barcode)}');
      continue;
    }
    String encoded = encode(parsed);
    print('$barcode   |   $parsed  |   $encoded');
  }
}

