      [2, 5],
      [3, 6],
    ],
    'nw': [
      [1, 2],
      [2, 3],
      [3, 4],
      [4, 5],
    ],
    'e': [
      [4, 2],
      [3, 3],
      [2, 4],
      [1, 5],
    ],
  };

  const Map<String, List<List<int>>> directions = {
    'n': [[-1, 0], [0, -1], [1, 0], [0, 1]],
    'ne': [[-1, 0], [0, -1], [1, 0], [1, 1]],
    'se': [[1, 0], [0, -1], [-1, 0], [1, 1]],
    'sw': [[1, 0], [0, -1], [-1, 0], [-1, 1]],
    'w': [[-1, 0], [0, -1], [0, 1], [1, 1]],
    's': [[-1, 0], [0, -1], [1, 0], [1, 1]],
    'nw': [[-1, 0], [0, -1], [1, 0], [-1, 1]],
    'e': [[1, 0], [0, -1], [-1, 0], [-1, 1]],
  };

  if (args.length < 2) {
    print('Usage: dart fn0.dart <square> <count>');
    print('Available squares: n,ne,se,sw,w,s,nw,e');
    print('Count must be >= 1.');
    return;
  }

  final String square = args[0];
  final int count = args.length >= 2 ? args[1].isEmpty ? 1 : args[1].toInt() : 1;

  if (!positions.containsKey(square)) {
    print('Invalid square: $square');
    return;
  }

  final List<List<int>> board = positions[square]!;
  final List<List<int>> dirs = directions[square]!;

  final Map<String, int> visited = {};
  final Map<String, int> moves = {};

  void backtrack(List<int> path) {
    if (path.length == count) {
      for (int i = 0; i < path.length; i++) {
        for (int j = 0; j < path.length; j++) {
          if (i == 0 && j == 0) continue;
          if (path[i] == board[j][path[j]]) {
            print(StringBuffer()..write(path.map((i) => i == 0 ? '.' : ' ').padRight(4)).toString());
            break;
          }
        }
      }
      return;
    }

    for (int d = 0; d < dirs.length; d++) {
      final List<int> dir = dirs[d];
      final int ni = path[0] + dir[0];
      final int nj = path[1] + dir[1];

      if (ni >= 0 && ni < board.length && nj >= 0 && nj < board[ni].length) {
        visited['${square}_${board[ni][nj]}'] = true;
        path.add(board[ni][nj]);
        backtrack(path);
        path.removeLast();
        visited.remove('${square}_${board[ni][nj]}');
      }
    }
  }

  backtrack([]);

  Map<String, int> freq = {};
  for (var key in visited.keys) {
    String name = key.split('_').first;
    freq[name] = (freq[name] ?? 0) + 1;
  }

  freq.forEach((key, count) {
    print('$key: $count');
  });
}

