void fn0() {

  const Map<int, String> squares = {
    0: 'A1', 1: 'A2', 2: 'A3', 3: 'A4',
    4: 'B1', 5: 'B2', 6: 'B3', 7: 'B4',
    8: 'C1', 9: 'C2', 10: 'C3', 11: 'C4',
    12: 'D1', 13: 'D2', 14: 'D3', 15: 'D4',
  };

  const int current = 13; 

  final List<List<int>> moves = [
    [-2, -1], [-2, 1], [-1, -2], [-1, 2],
    [1, -2], [1, 2], [2, -1], [2, 1],
  ];

  void printBoard() {
    for (int i = 0; i < 4; i++) {
      String row = '';
      for (int j = 0; j < 4; j++) {
        row += squares[i * 4 + j].padRight(2);
      }
      print(row);
    }
    print('');
  }

  printBoard();

  Map<String, int> fileCounts = {};
  Map<String, int> rankCounts = {};

  void search(int file, int rank, int depth) {
    if (depth == 2) {
      String key = '$file.$rank';
      fileCounts[key] = (fileCounts[key] ?? 0) + 1;
      rankCounts[key] = (rankCounts[key] ?? 0) + 1;
      return;
    }

    for (final m in moves) {
      int nf = file + m[0];
      int nr = rank + m[1];
      if (nf >= 0 && nf < 4 && nr >= 0 && nr < 4) {
        search(nf, nr, depth + 1);
      }
    }
  }

  for (int f = 0; f < 4; f++) {
    for (int r = 0; r < 4; r++) {
      search(f, r, 0);
    }
  }

  Map<String, int> bestFileCounts = {};
  Map<String, int> bestRankCounts = {};

  fileCounts.forEach((key, count) {
    if (count > bestFileCounts[key] ?? 0) {
      bestFileCounts[key] = count;
    }
  });

  rankCounts.forEach((key, count) {
    if (count > bestRankCounts[key] ?? 0) {
      bestRankCounts[key] = count;
    }
  });

  StringBuffer sb = StringBuffer();
  bestFileCounts.forEach((key, count) {
    sb.write('$key:$count ');
  });
  print(sb.toString());

  sb = StringBuffer();
  bestRankCounts.forEach((key, count) {
    sb.write('$key:$count ');
  });
  print(sb.toString());
}

