@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String str = 'Hello World';

  String binary(String str) {
    return str.split('').map((c) {
      String hex = c.toRadixString(16).toUpperCase();
      if (hex.length == 1) {
        hex = '0$hex';
      }
      return hex;
    }).join();
  }

  String ascii(String str) {
    List<String> codes = str.split('').map((c) {
      int code = c.codeUnitAt(0);
      String hex = code.toRadixString(16).toUpperCase().padLeft(2, '0');
      return '$code:$hex';
    }).toList();
    return codes.join(' ');
  }

  String hex(String str) {
    List<String> codes = str.split('').map((c) {
      int code = c.codeUnitAt(0);
      String hex = code.toRadixString(16).toUpperCase().padLeft(2, '0');
      return '$code:$hex';
    }).toList();
    return codes.join(' ');
  }

  print('Binary: ${binary(str)}');
  print('Ascii: ${ascii(str)}');
  print('Hex: ${hex(str)}');

  String decode(String s) {
    String decoded = '';
    int i = 0;

    while (i < s.length) {

      String block = '';
      while (i < s.length && s.codeUnitAt(i) >= 48 && s.codeUnitAt(i) <= 57) {
        block += s[i];
        i++;
      }

      if (block.isEmpty) {
        decoded += s[i];
        i++;
        continue;
      }

      int count = int.parse(block);
      String symbol = s[i];
      i++;

      for (int j = 0; j < count; j++) {
        decoded += symbol;
      }
    }

    return decoded;
  }

  String base64 = 'QWxhZGRpbGl0IHwgZ21haW4gYmlsbGQhQWxpZ2VjIHsK';
  String decoded = decode(base64);
  print('Decoded base64: $decoded');
}

