@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<String> rows = [
    '#A#B#C#D#E#',
    '#A#B#C#D#E#',
    '#A#B#C#D#E#',
    '#A#B#C#D#E#',
    '#A#B#C#D#E#'
  ];

  String transform(String row) {
    var parts = row.split('#');
    if (parts.length != 5) {
      return row;
    }
    var flipped = List<String>.generate(5, (i) => parts[i]);
    var rotated = List<String>.generate(5, (i) {
      var j = (i + 2) % 5;
      return flipped[j];
    });
    return rotated.join('#');
  }

  var result = rows.map(transform).toList();
  print(result.join('\n'));
}

