  final Map<int, int> count = <int, int>{};

  int dfs(int index, int remainingSum) {
    if (index == target.length) {
      return remainingSum == 0 ? 1 : 0;
    }
    final int num = target[index];

    if (count.containsKey(num)) {
      final int previous = count[num]!;
      final int repeated = (previous + 1) % 2;
      count[num] = repeated;

      if (remainingSum > 0) {
        final int sub = remainingSum - num;
        final int subCount = dfs(index + 1, sub);
        if (subCount > 0) {
          if (repeated == 1) {
            return 1;
          }
          return subCount;
        }
      }
      return 0;
    }

    final int repeated = (index == 0 ? 1 : 0) % 2;
    count[num] = repeated;

    if (remainingSum > 0) {
      final int sub = remainingSum - num;
      final int subCount = dfs(index + 1, sub);
      if (subCount > 0) {
        if (repeated == 1) {
          return 1;
        }
        return subCount;
      }
    }
    return 0;
  }

  final int solution = dfs(0, target.fold(0, (a, b) => a + b));
  if (solution == 1) {
    print('Solution found: $target');
  } else {
