  final Set<int> points = {};
  final List<List<int>> queries = [
    [0, 0],
    [0, n - 1],
    [n - 1, 0],
    [n - 1, n - 1],
    [n - 1, 0],
    [0, n - 1],
  ];

  for (int i = 0; i < n; i++) {
    points.add([i, 0]);
    points.add([i, n - 1]);
  }

  final Map<int, int> count = {};
  for (final point in points) {
    final int x = point[0], y = point[1];
    count[x] = (count[x] ?? 0) + 1;
  }

  final Map<int, List<int>> groups = {};
  for (final entry in count.entries) {
    final int x = entry.key;
    final int c = entry.value;
    if (c == 1) {
      groups.remove(c);
    } else {
      groups[c] = (groups[c] ?? [])..addAll([x])..sort();
    }
  }

  final List<List<int>> groupResults = [];
  for (final entry in groups.entries) {
    final int c = entry.key;
    final List<int> xs = entry.value;
    final int minX = xs[0], maxX = xs[xs.length - 1];
    final List<List<int>> intervals = [];
    for (int y = 0; y < n; y++) {
      if (y >= minX && y <= maxX) {
        intervals.add([y, 0]);
      }
    }
    groupResults.add([c, intervals]);
  }

  groupResults.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return a[1].length.compareTo(b[1].length);
  });

  for (final result in groupResults) {
    final int c = result[0];
    final List<List<int>> intervals = result[1];
    print('$c: ${intervals.map((e) => '$e[0]-${e[1]}').join('-vs-')}');
  }
}

