List<int> fn0(List<int> sortedPricesCents, List<int> minDischarge, List<int> maxDischarge, int capacity) {
  if (minDischarge.isEmpty || maxDischarge.isEmpty || sortedPricesCents.isEmpty) {
    return <int>[];
  }

  List<int> windows = <int>[];
  int i = 0;

  while (i < sortedPricesCents.length) {
    int low = i;
    int high = sortedPricesCents.length - 1;
    while (low < high) {
      int mid = (low + high) >> 1;
      if (sortedPricesCents[mid] <= sortedPricesCents[i]) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }

    int bestStart = low;
    int bestLen = 0;
    int total = 0;

    for (int j = low; j < sortedPricesCents.length; j++) {
      total += sortedPricesCents[j];
      if (total > capacity) {
        break;
      }

      while (total > capacity && j > bestStart) {
        total -= sortedPricesCents[bestStart];
        bestStart++;
      }

      int currLen = j - bestStart + 1;
      if (currLen > bestLen) {
        bestLen = currLen;
      }
    }

    if (bestLen > 0) {
      int lo = minDischarge[bestStart];
      int hi = maxDischarge[bestStart];
      while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (total + mid <= capacity) {
          lo = mid + 1;
        } else {
          hi = mid;
        }
      }

      int bestEnd = lo - 1;
      windows.add(bestEnd - bestStart + 1);
    }

    i = low;
  }

  return windows;
}

