Map<String, int> fn0(List<String> codes, List<int> minutes, int targetMinutes) {
  if (codes.isEmpty || minutes.isEmpty) return {};
  int n = codes.length;
  int totalWait = 0;
  for (int i = 0; i < n; i++) {
    totalWait += minutes[i];
  }
  int left = 0, right = n - 1, ans = 0;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int sum = 0;
    for (int i = 0; i <= mid; i++) {
      sum += minutes[i];
    }
    if (sum >= targetMinutes) {
      ans = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  List<String> prefix = [];
  for (int i = 0; i < n; i++) {
    if (i == 0) {
      prefix.add(codes[0]);
    } else {
      prefix.add(codes[i] == codes[i - 1] ? prefix[i - 1] : codes[i]);
    }
  }
  return {
    'prefix$ans': prefix[ans],
    'totalWait$ans': totalWait,
  };
}

