Map<String, int> fn0(List<String> shelfCodes, int maxGap) {
  if (shelfCodes.isEmpty || maxGap <= 0) return {};
  int n = shelfCodes.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int best = -1;
    for (int j = i - 1; j >= 0; j--) {
      int gap = shelfCodes[i - 1].length - shelfCodes[j].length;
      if (gap <= maxGap) {
        if (dp[j] == -1 || dp[j] > best) best = dp[j];
      }
    }
    if (best == -1) best = 0;
    dp[i] = best + 1;
  }
  Map<String, int> result = {};
  for (int i = 0; i < n; i++) {
    result[shelfCodes[i]] = dp[i + 1];
  }
  return result;
}

