  for (int i = 1; i <= n; i++) {
    prefix[i] = prefix[i - 1] + arr[i - 1];
  }

  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(n + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      int cost = arr[i - 1] + arr[j - 1] + (i > j ? 1 : 0);
      dp[i][j] = cost > 0 ? dp[i - 1][j] + dp[i][j - 1] + cost : 0;
    }
  }

  List<List<int>> minCost = List.generate(n + 1, (_) => List.filled(n + 1, 0));
  List<List<int>> minPath = List.generate(n + 1, (_) => List.filled(n + 1, 0));

