  void printPath(List<List<int>> grid, int i, int j) {
    if (i == 0 && j == 0) {
      print(arr[0]);
      return;
    }
    int prev = dp[i][j];
    int up = dp[i - 1][j];
    int left = dp[i][j - 1];
    if (up <= prev) {
      printPath(grid, i - 1, j);
    } else if (left <= prev) {
      printPath(grid, i, j - 1);
    }
  }

  int minCostVal = dp[1][1];
  minCost[1][1] = minCostVal;
  minPath[1][1] = [1];
  for (int size = 2; size <= n; size++) {
    for (int i = 1; i <= n - size + 1; i++) {
      int j = i + size - 1;
