      for (int k = i; k <= j - 1; k++) {
        if (dp[i][k] != 0 && dp[k + 1][j] != 0) {
          if (dp[i][k] + dp[k + 1][j] < minCostVal) {
            minCostVal = dp[i][k] + dp[k + 1][j];
          }
        }
      }
    }
  }

  print('Minimum cost: $minCostVal');
  printPath(minPath, 1, 1);
}

