Map<String, int> fn0(List<String> timetable) {
  if (timetable.isEmpty) {
    return {};
  }

  Map<String, int> departures = {};
  for (String route in timetable) {
    List<String> parts = route.split(':');
    if (parts.length != 2) {
      continue;
    }

    String minutes = parts[1];
    List<String> segments = minutes.split('-');
    if (segments.length != 2) {
      continue;
    }

    String start = segments[0];
    String end = segments[1];
    if (start.isEmpty || end.isEmpty) {
      continue;
    }

    int startMinutes = 0;
    int endMinutes = 0;
    int colonIndex = start.indexOf(':');
    if (colonIndex > 0) {
      startMinutes = int.parse(start.substring(0, colonIndex));
      start = start.substring(colonIndex + 1);
    }

    colonIndex = end.indexOf(':');
    if (colonIndex > 0) {
      endMinutes = int.parse(end.substring(0, colonIndex));
      end = end.substring(colonIndex + 1);
    }

    if (startMinutes >= 0 && startMinutes <= 59 &&
        endMinutes >= 0 && endMinutes <= 59) {
      for (int minute = startMinutes; minute <= endMinutes; minute++) {
        departures[minute] = (departures[minute] ?? 0) + 1;
      }
    }
  }

  List<String> keys = departures.keys.toList();
  keys.sort((String a, String b) {
    int cmp = a.compareTo(b);
    if (cmp != 0) {
      return cmp;
    }

    int departA = int.parse(a);
    int departB = int.parse(b);
    if (departA != departB) {
      return departB.compareTo(departA);
    }

    int countA = departures[a]!;
    int countB = departures[b]!;
    if (countB != countA) {
      return countA.compareTo(countB);
    }

    return 0;
  });

  int first = keys.first;
  int last = keys.last;
  return {
    'first': first,
    'last': last,
    'interval': last - first,
    'total': departures[first]!,
  };
}

