  for (int i = 0; i < edits.length; i++) {
    Map<String, Object> edit = {
      'id': i,
      'text': edits[i],
      'weight': weights[i],
      'capacity': capacity,
      'done': false,
      'priority': 0,
    };
    if (i > 0) {
      edit['priority'] = (edit['priority'] as int).compareTo(items[i - 1]['priority'] as int);
    }
    items.add(edit);
  }
  items.sort((a, b) => (b['priority'] as int).compareTo(a['priority'] as int));
  for (var item in items) {
    int id = item['id'] as int;
    String text = item['text'] as String;
    int weight = item['weight'] as int;
    int capacity = item['capacity'] as int;
    bool done = item['done'] as bool;
    int priority = item['priority'] as int;
    if (done || weight > capacity) continue;
    int end = 0;
    bool accepted = false;
    for (int j = 0; j < id && j < result.length; j++) {
      int key = result.keys.first;
      String prevText = result[key]!;
      if (text.compareTo(prevText) == 0) {
        end = j;
        accepted = true;
        break;
      }
      if (text.isEmpty) {
        result.remove(key);
        continue;
      }
      if (prevText.isEmpty && text.isNotEmpty) {
        result[text] = weight;
      } else if (prevText.isNotEmpty && text.isEmpty) {
        result.remove(key);
      } else if (prevText.compareTo(text) > 0) {
        result[text] = weight;
      } else {
        int delta = weight - prevText.length;
        if (delta > 0) {
          result[text] = result[key]! + delta;
        } else if (delta < 0) {
          result[text] = result[key]! - delta;
        }
      }
      key = result.keys.first;
    }
    if (accepted) {
      result[text] = end + 1;
    } else {
      result[text] = -1;
    }
  }
  for (int i = 0; i < items.length; i++) {
    if (items[i]['done'] as bool) continue;
    String text = items[i]['text'] as String;
    int? count = result[text];
    if (count == null || count < 0) {
      result[text] = -1;
    } else {
      result[text] = count;
    }
  }
  return result;
}

