bool fn0(List<List<int>> logGrid, List<int> target) {
  if (logGrid.isEmpty || logGrid[0].isEmpty) return false;

  int rows = logGrid.length;
  int cols = logGrid[0].length;

  if (target.isEmpty) {
    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        if (logGrid[i][j] == -1) return true;
      }
    }
    return false;
  }

  Map<int, int> counts = {};
  int minVal = target[0];
  int maxVal = target[0];

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int val = logGrid[i][j];
      if (val < minVal) minVal = val;
      if (val > maxVal) maxVal = val;

      counts[val] = (counts[val] ?? 0) + 1;
    }
  }

  List<int> indices = [];
  for (int i = minVal; i <= maxVal; i++) {
    indices.add(i);
  }

  indices.sort((a, b) {
    int cmp = b.compareTo(a);
    if (cmp != 0) return cmp;
    return a.compareTo(b);
  });

  List<List<int>> valid = [];

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int val = logGrid[i][j];
      if (val >= minVal && val <= maxVal) {
        valid.add([i, j, val]);
      }
    }
  }

  valid.sort((a, b) {
    int cmp = a[2].compareTo(b[2]);
    if (cmp != 0) return cmp;
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return a[1].compareTo(b[1]);
  });

  for (List<int> rect in valid) {
    int lo = rect[0];
    int hi = rect[1];
    int mid = rect[2];

    bool covered = false;

    for (int k = 0; k < indices.length; k++) {
      if (indices[k] == mid) {
        covered = true;
        break;
      }
    }

    if (covered) {
      bool left = false;
      bool right = false;

      for (int k = lo; k < hi; k++) {
        int v = logGrid[rect[0]][k];
        if (v >= minVal && v <= maxVal) {
          left = true;
        }
        int r = rect[1];
        if (k >= r) break;
      }

      for (int k = lo; k < hi; k++) {
        int v = logGrid[k][rect[1]];
        if (v >= minVal && v <= maxVal) {
          right = true;
        }
      }

      if (left && right) {
        return true;
      }
    }
  }

  return false;
}

