  List<int> left = fn0(readings, start, mid);
  List<int> right = fn0(readings, mid, end);
  List<int> merged = [];
  int i = 0, j = 0, k = 0;
  while (i < left.length && j < right.length) {
    if (left[i] >= 0) {
      merged.add(left[i++]);
      k++;
    } else {
      merged.add(right[j++]);
      k++;
    }
  }
  while (i < left.length) merged.add(left[i++]);
  while (j < right.length) merged.add(right[j++]);
  return merged;
}

