class Circle {
  final double cx;
  final double cy;
  final double r;

  Circle(this.cx, this.cy, this.r);

  bool contains(Point p) =>
      (p.x - cx).abs() * (p.x - cx).abs() +
      (p.y - cy).abs() * (p.y - cy).abs() <= r * r;

  bool overlaps(Circle other) =>
      other.cx + other.r > cx - other.r &&
      other.cx - other.r < cx + other.r &&
      other.cy + other.r > cy - other.r &&
      other.cy - other.r < cy + other.r;

  @override
  String toString() => 'Circle[cx=$cx, cy=$cy, r=$r)';
}

