void fn0() {

  final random = Random(0);

  final rows = <int>[1, 2, 3, 4];
  final cols = <int>[1, 2, 3, 4];

  final rowsCount = rows.length;
  final colsCount = cols.length;

  final board = List.generate(
    rowsCount,
    (_) => List.from(cols)
      ..shuffle(random)
      ..filled(0, 0)
  );

  List<int> queenPositions = <int>[];

  bool isSafe(int row, int col) {
    for (int r = 0; r < row; r++) {
      if (board[r][col] == 1) return false;
    }

    int r = row - 1;
    int c = col - 1;
    while (r >= 0 && c >= 0) {
      if (board[r][c] == 1) return false;
      r--;
      c--;
    }

    r = row - 1;
    c = col + 1;
    while (r >= 0 && c < colsCount) {
      if (board[r][c] == 1) return false;
      r--;
      c++;
    }

    return true;
  }

  bool place(int row) {
    for (int col = 0; col < colsCount; col++) {
      if (isSafe(row, col)) {
        board[row][col] = 1;
        if (place(row + 1)) return true;
        board[row][col] = 0;
      }
    }

    return false;
  }

  if (place(0)) {
    for (int r = 0; r < rowsCount; r++) {
      for (int c = 0; c < colsCount; c++) {
        if (board[r][c] == 1) {
          queenPositions.add(<int>{r, c});
        }
      }
    }
  }

  print('퀸配置 (x, y):');
  for (var pos in queenPositions) {
    print('${pos.keys[0]}, ${pos.keys[1]}');
  }
}

