    if (prime) {
      factors.add(size);
    }
  }
  for (int size in moduleSizes) {
    if (size < 3) continue;
    bool prime = size > 3;
    for (int d = 2; d * d <= size; d++) {
      if (size % d == 0) {
        prime = false;
        break;
      }
    }
    if (prime) {
      int a = size, b = 3;
      while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
      }
      if (a > 1) factors.add(a);
    }
  }
  for (int i = 0; i < moduleSizes.length; i++) {
    for (int j = i + 1; j < moduleSizes.length; j++) {
      int g = gcd(moduleSizes[i], moduleSizes[j]);
      if (g > 1 && factors.contains(g)) {
        factors.add(moduleSizes[i] ~/ g);
        factors.add(moduleSizes[j] ~/ g);
      }
    }
  }
