class Queue<T> {
  List<T> items = [];
  void add(T item) {
    items.add(item);
  }
  T removeFirst() {
    if (items.isEmpty) return null;
    return items.removeFirst();
  }
}

class PriorityQueue<T> extends Queue<T> {

  List<T> items = [];

  @override
  void add(T item) {
    if (items.isEmpty || item.priority > items.last.priority) {
      items.add(item);
    } else {
      Queue<T>.removeFirst();
      add(item);
    }
  }
}

class Node<T> {
  T value;
  Node<T>? left;
  Node<T>? right;
  Node<T>? parent;
  int height;
  int depth;

  Node(this.value, {this.left, this.right, this.parent, this.height = 0, this.depth = 0});
}

class BinaryTree<T> {
  Node<T>? root;

  void _height(Node<T>? node, int h) {
    node?.height = h;
    if (node?.left != null) _height(node.left, h + 1);
    if (node?.right != null) _height(node.right, h + 1);
  }

  void _depth(Node<T>? node, int d) {
    node?.depth = d;
    if (node?.left != null) _depth(node.left, d + 1);
    if (node?.right != null) _depth(node.right, d + 1);
  }

  void _print(Node<T>? node, String indent) {
    if (node == null) return;
    _print(node.left, indent + '  ');
    print('$indent${node.value} (h = ${node.height}, d = ${node.depth})');
    _print(node.right, indent + '  ');
  }

  void insert(T value) {
    Node<T>? node = root;
    Node<T>? parent = null;
    while (node != null) {
      parent = node;
      if (value.compareTo(node.value) < 0) {
        node = node.left;
      } else {
        node = node.right;
      }
    }
    node = parent;
