class PriorityQueue<T extends Comparable<T>> implements Queue<T> {
  List<T> queue = [];

  @override
  void add(T item) {
    queue.add(item);
  }

  @override
  T removeFirst() {
    if (queue.isEmpty) return null;
    int maxPriority = queue[0].compareTo(null);
    for (int i = 1; i < queue.length; i++) {
      int curr = queue[i].compareTo(null);
      if (curr > maxPriority) {
        maxPriority = curr;
      }
    }
    T maxItem = queue.removeAt(maxPriority);
    return maxItem;
  }
}

